input.content:
:root {
  color-scheme: light dark;

  --paper: #f5f1e7;
  --paper-deep: #ece5d5;
  --ink: #17140f;
  --ink-soft: rgba(23, 20, 15, 0.68);
  --ink-faint: rgba(23, 20, 15, 0.45);
  --rule: rgba(23, 20, 15, 0.22);
  --accent: #8a2b1f;
  --accent-wash: rgba(138, 43, 31, 0.09);
  --field: #fffdf7;

  --serif: Georgia, "Iowan Old Style", "Times New Roman", Times, serif;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial,
    sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas,
    "Liberation Mono", monospace;

  --fs-display: clamp(2.6rem, 9.5vw, 5.75rem);
  --fs-title: clamp(1.1875rem, 1rem + 1.1vw, 1.5rem);
  --fs-body: 1.0625rem;
  --fs-lede: clamp(1.0625rem, 0.98rem + 0.5vw, 1.1875rem);
  --fs-label: 0.6875rem;
  --fs-micro: 0.75rem;

  --pad: clamp(1.25rem, 4.5vw, 4.5rem);
  --rule-thin: 1px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --paper: #14130f;
    --paper-deep: #1c1a15;
    --ink: #efe8d8;
    --ink-soft: rgba(239, 232, 216, 0.7);
    --ink-faint: rgba(239, 232, 216, 0.5);
    --rule: rgba(239, 232, 216, 0.26);
    --accent: #e5836d;
    --accent-wash: rgba(229, 131, 109, 0.14);
    --field: #1a1915;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--serif);
  font-size: var(--fs-body);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3,
p,
ul,
ol,
figure,
blockquote {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.22em;
}

img,
svg {
  display: block;
  max-width: 100%;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 1px;
}

.wrap {
  width: 100%;
  max-width: 96rem;
  margin-inline: auto;
  padding-inline: var(--pad);
}

.skip-link {
  position: absolute;
  left: 0.75rem;
  top: -4rem;
  z-index: 10;
  padding: 0.6rem 0.9rem;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  transition: top 120ms ease;
}

.skip-link:focus-visible {
  top: 0.75rem;
}

.kicker {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.kicker__rule {
  display: block;
  width: clamp(1.75rem, 5vw, 3.5rem);
  border-top: 2px solid var(--accent);
}

.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 1.5rem;
  padding-bottom: 0.85rem;
  border-bottom: var(--rule-thin) solid var(--ink);
}

.section-title {
  font-size: var(--fs-title);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.005em;
  text-wrap: balance;
}

.section-note {
  font-family: var(--mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.02em;
  color: var(--ink-faint);
}

.masthead {
  border-bottom: 3px double var(--ink);
}

.masthead__bar {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 0.6rem;
  border-bottom: var(--rule-thin) solid var(--rule);
}

.masthead__meta {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.masthead__meta--right {
  display: none;
}

.masthead__stack {
  padding-block: clamp(1.5rem, 5vw, 2.75rem) 0;
  text-align: center;
}

.masthead__eyebrow {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--accent);
}

.wordmark {
  margin-block: 0.35rem 0.5rem;
  font-size: clamp(3rem, 17vw, 8.5rem);
  font-weight: 400;
  line-height: 0.9;
  letter-spacing: 0.02em;
}

.masthead__strap {
  max-width: 32rem;
  margin-inline: auto;
  font-size: var(--fs-micro);
  font-style: italic;
  line-height: 1.5;
  color: var(--ink-soft);
}

.masthead__foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1.5rem;
  margin-top: clamp(1.25rem, 4vw, 2rem);
  padding-block: 0.7rem;
  border-top: var(--rule-thin) solid var(--rule);
}

.nav__list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 1.25rem;
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.nav__list a {
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
}

.nav__list a:hover,
.nav__list a:focus-visible {
  border-bottom-color: var(--accent);
  color: var(--accent);
}

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.4rem 0.7rem;
  border: var(--rule-thin) solid var(--ink);
  background: none;
  color: inherit;
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
}

.toggle:hover {
  background: var(--accent-wash);
}

.toggle__state {
  min-width: 2.1em;
  padding: 0.15em 0.35em;
  border: var(--rule-thin) solid var(--rule);
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.06em;
  text-align: center;
  color: var(--ink-soft);
}

.toggle[aria-pressed="true"] {
  border-color: var(--accent);
}

.toggle[aria-pressed="true"] .toggle__state {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--field);
}

.cover {
  padding-block: clamp(2.25rem, 7vw, 4.5rem) clamp(1.5rem, 4vw, 2.5rem);
}

.cover__grid {
  display: grid;
  gap: clamp(1.75rem, 4vw, 3rem);
}

.display {
  margin-top: 1rem;
  font-size: var(--fs-display);
  font-weight: 400;
  line-height: 0.92;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.byline {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 0.9rem;
  margin-top: 1.25rem;
  padding-top: 0.7rem;
  border-top: var(--rule-thin) solid var(--rule);
}

.byline__name {
  font-size: 1.0625rem;
  font-style: italic;
}

.byline__kind {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.cover__aside {
  display: grid;
  gap: clamp(1.5rem, 3vw, 2.25rem);
}

.lede {
  max-width: 34rem;
  font-size: var(--fs-lede);
  line-height: 1.62;
  text-wrap: pretty;
}

.lede::first-letter {
  float: left;
  margin-right: 0.09em;
  margin-top: 0.06em;
  font-size: 3.3em;
  line-height: 0.78;
  font-weight: 700;
  color: var(--accent);
}

.pullquote {
  max-width: 26rem;
  padding-left: 1.1rem;
  border-left: 2px solid var(--ink);
  font-size: clamp(1.125rem, 1rem + 1vw, 1.5rem);
  font-style: italic;
  line-height: 1.3;
  text-wrap: balance;
}

.figure {
  display: grid;
  gap: 0.7rem;
}

.figure__art {
  width: 100%;
  height: auto;
  color: var(--ink);
}

.figure__caption {
  max-width: 30rem;
  padding-top: 0.6rem;
  border-top: var(--rule-thin) solid var(--rule);
  font-family: var(--sans);
  font-size: var(--fs-micro);
  line-height: 1.5;
  color: var(--ink-soft);
}

.gauge {
  margin-top: clamp(2rem, 5vw, 3.5rem);
  padding-top: 1rem;
  border-top: var(--rule-thin) solid var(--ink);
}

.gauge__title {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.gauge__marks {
  display: flex;
  gap: clamp(0.5rem, 2vw, 1.5rem);
  margin-top: 1rem;
}

.gauge__mark {
  position: relative;
  flex: 1 1 0;
  height: 4rem;
}

.gauge__line {
  position: absolute;
  left: 0;
  right: 0;
  bottom: var(--level);
  border-top: var(--rule-thin) solid var(--ink);
}

.gauge__year {
  position: absolute;
  left: 0;
  bottom: calc(var(--level) + 0.28rem);
  font-family: var(--mono);
  font-size: var(--fs-micro);
  line-height: 1;
  color: var(--ink);
}

.gauge__value {
  position: absolute;
  left: 0;
  bottom: 0;
  font-family: var(--sans);
  font-size: 0.625rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.gauge__mark--now::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--level);
  background: var(--accent-wash);
}

.gauge__mark--now .gauge__line {
  border-top: 2px solid var(--accent);
}

.gauge__mark--now .gauge__year,
.gauge__mark--now .gauge__value {
  color: var(--accent);
}

.issues {
  padding-block: clamp(2rem, 5vw, 3.5rem);
  border-top: var(--rule-thin) solid var(--rule);
}

.stories {
  display: grid;
  gap: clamp(1.75rem, 4vw, 3rem);
  margin-top: clamp(1.5rem, 4vw, 2.5rem);
}

.story {
  display: grid;
  gap: 0.5rem;
  align-content: start;
}

.story + .story {
  padding-top: clamp(1.5rem, 3vw, 2.5rem);
  border-top: var(--rule-thin) solid var(--rule);
}

.story__num {
  font-family: var(--mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--accent);
}

.story__title {
  font-size: var(--fs-title);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.01em;
}

.story__by {
  font-size: var(--fs-micro);
  font-style: italic;
  color: var(--ink-soft);
}

.story__sum {
  max-width: 38ch;
  color: var(--ink-soft);
  text-wrap: pretty;
}

.story--wide {
  display: grid;
  gap: 1rem;
}

.archive {
  padding-block: clamp(2rem, 5vw, 3.5rem);
  border-top: var(--rule-thin) solid var(--rule);
}

.archive__list {
  display: grid;
  margin-top: clamp(1.25rem, 3vw, 2rem);
  border-top: var(--rule-thin) solid var(--rule);
}

.archive__item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.35rem 1.25rem;
  padding-block: 0.85rem;
  border-bottom: var(--rule-thin) solid var(--rule);
}

.archive__no {
  min-width: 5.5rem;
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.archive__title {
  font-size: 1.0625rem;
  font-style: italic;
}

.offer {
  padding-block: clamp(2.5rem, 6vw, 4.5rem);
  border-top: var(--rule-thin) solid var(--rule);
}

.offer__grid {
  display: grid;
  gap: clamp(2rem, 5vw, 4rem);
}

.offer__copy {
  display: grid;
  gap: 1.1rem;
  align-content: start;
}

.offer__price {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.2rem 0.6rem;
  padding-top: 0.4rem;
}

.offer__currency {
  font-size: 1.5rem;
  color: var(--ink-soft);
}

.offer__amount {
  font-size: clamp(3rem, 9vw, 4.75rem);
  line-height: 0.85;
  letter-spacing: -0.03em;
}

.offer__per {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
}

.offer__list {
  display: grid;
  gap: 0.5rem;
  max-width: 34rem;
  color: var(--ink-soft);
}

.offer__list li {
  padding-left: 1.1rem;
  position: relative;
}

.offer__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.65em;
  width: 0.5rem;
  border-top: var(--rule-thin) solid var(--accent);
}

.form {
  display: grid;
  gap: 1.1rem;
  align-content: start;
  padding: clamp(1.25rem, 3vw, 2rem);
  border: var(--rule-thin) solid var(--ink);
  background: var(--field);
}

.form__field {
  display: grid;
  gap: 0.45rem;
}

.form__label {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-soft);
}

.form__input {
  width: 100%;
  padding: 0.7rem 0.8rem;
  border: var(--rule-thin) solid var(--rule);
  border-bottom-color: var(--ink);
  background: transparent;
  color: inherit;
  font-family: var(--mono);
  font-size: 0.9375rem;
}

.form__input::placeholder {
  color: var(--ink-faint);
}

.form__input:hover {
  border-color: var(--ink-soft);
}

.form__input[aria-invalid="true"] {
  border-color: var(--accent);
  background: var(--accent-wash);
}

.form__hint,
.form__feedback {
  font-family: var(--sans);
  font-size: var(--fs-micro);
  line-height: 1.45;
  color: var(--ink-faint);
}

.form__feedback:empty {
  display: none;
}

.form__feedback[data-state="error"] {
  color: var(--accent);
}

.form__feedback[data-state="success"] {
  font-family: var(--serif);
  font-size: 1rem;
  font-style: italic;
  color: var(--ink);
}

.button {
  justify-self: start;
  padding: 0.75rem 1.4rem;
  border: var(--rule-thin) solid var(--ink);
  background: var(--ink);
  color: var(--paper);
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: pointer;
}

.button:hover {
  background: var(--accent);
  border-color: var(--accent);
}

.form__fine {
  font-family: var(--sans);
  font-size: 0.6875rem;
  line-height: 1.5;
  color: var(--ink-faint);
}

.footer {
  border-top: 3px double var(--ink);
  background: var(--paper-deep);
}

.footer__grid {
  display: grid;
  gap: 1.75rem;
  padding-block: clamp(2rem, 4vw, 3rem);
}

.footer__mark {
  font-size: 1.5rem;
  letter-spacing: 0.02em;
}

.footer__head {
  font-family: var(--sans);
  font-size: var(--fs-label);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.footer__text {
  margin-top: 0.4rem;
  font-size: var(--fs-micro);
  line-height: 1.55;
  color: var(--ink-soft);
}

.footer__mail {
  font-family: var(--mono);
}

@media (min-width: 40rem) {
  .masthead__meta--right {
    display: block;
  }

  .footer__grid {
    grid-template-columns: 1.6fr 1fr 1fr;
    gap: clamp(1.5rem, 4vw, 3.5rem);
  }

  .archive__item {
    flex-wrap: nowrap;
  }
}

@media (min-width: 60rem) {
  .cover__grid {
    grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
    gap: clamp(2rem, 5vw, 5rem);
  }

  .cover__aside {
    padding-top: clamp(0.5rem, 3vw, 4.5rem);
  }

  .stories {
    grid-template-columns: repeat(12, minmax(0, 1fr));
    gap: clamp(1.5rem, 3vw, 3rem) clamp(1.5rem, 3vw, 3rem);
  }

  .story + .story {
    padding-top: 0;
    border-top: 0;
  }

  .story:nth-child(1) {
    grid-column: 1 / span 5;
  }

  .story:nth-child(2) {
    grid-column: 7 / span 6;
    margin-top: clamp(2.5rem, 6vw, 5.5rem);
  }

  .story:nth-child(3) {
    grid-column: 3 / span 9;
    margin-top: clamp(2rem, 4vw, 3.5rem);
    padding-top: clamp(1.5rem, 3vw, 2.5rem);
    border-top: var(--rule-thin) solid var(--rule);
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
    gap: 0.75rem clamp(1.5rem, 3vw, 3rem);
  }

  .story:nth-child(3) .story__sum {
    max-width: 46ch;
  }

  .gauge__mark {
    height: 5rem;
  }

  .offer__grid {
    grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
    align-items: start;
  }
}

html[data-reading="on"] {
  --fs-body: 1.1875rem;
  --fs-lede: 1.25rem;
  --pad: clamp(1.25rem, 4vw, 3.5rem);
}

html[data-reading="on"] body {
  line-height: 1.75;
}

html[data-reading="on"] .masthead__strap,
html[data-reading="on"] .pullquote,
html[data-reading="on"] .figure,
html[data-reading="on"] .gauge,
html[data-reading="on"] .section-note,
html[data-reading="on"] .story__num {
  display: none;
}

html[data-reading="on"] .cover__grid,
html[data-reading="on"] .issues,
html[data-reading="on"] .archive,
html[data-reading="on"] .offer__grid {
  max-width: 42rem;
}

html[data-reading="on"] .issues,
html[data-reading="on"] .archive,
html[data-reading="on"] .offer {
  border-top: 0;
}

html[data-reading="on"] .stories,
html[data-reading="on"] .archive__list,
html[data-reading="on"] .offer__grid {
  gap: 2.75rem;
}

html[data-reading="on"] .story + .story {
  padding-top: 2.75rem;
  border-top: var(--rule-thin) solid var(--rule);
}

html[data-reading="on"] .story:nth-child(n) {
  grid-column: 1 / -1;
  margin-top: 0;
}

html[data-reading="on"] .display {
  font-size: clamp(2.25rem, 7vw, 3.5rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
}

html[data-reading="on"] .story__sum,
html[data-reading="on"] .offer__list,
html[data-reading="on"] .lede {
  max-width: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

(function () {
  "use strict";

  var root = document.documentElement;
  root.classList.add("js");

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  var STORAGE_KEY = "margin-reading-mode";

  function readStored() {
    try {
      return window.localStorage.getItem(STORAGE_KEY);
    } catch (err) {
      return null;
    }
  }

  function writeStored(value) {
    try {
      window.localStorage.setItem(STORAGE_KEY, value);
    } catch (err) {
      return;
    }
  }

  var toggle = document.querySelector("[data-reading-toggle]");
  var toggleState = document.querySelector("[data-reading-state]");

  function setReadingMode(on) {
    root.setAttribute("data-reading", on ? "on" : "off");
    if (toggle) {
      toggle.setAttribute("aria-pressed", on ? "true" : "false");
    }
    if (toggleState) {
      toggleState.textContent = on ? "On" : "Off";
    }
    writeStored(on ? "on" : "off");
  }

  setReadingMode(readStored() === "on");

  if (toggle) {
    toggle.addEventListener("click", function () {
      setReadingMode(root.getAttribute("data-reading") !== "on");
    });
  }

  var form = document.querySelector("[data-subscribe]");
  var email = document.getElementById("email");
  var feedback = document.querySelector("[data-feedback]");

  var EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

  var MESSAGES = {
    empty: "Enter an email address so we know where to send the first issue.",
    invalid: "That address is not quite right — check for a missing @ or a typo.",
    success: "Thank you. That address works; confirmation is on its way."
  };

  function showFeedback(state, message) {
