      var fs=Math.round(parseFloat(getComputedStyle(disp).fontSize));
      var wm=d.querySelector('.wordmark');
      var wmfs=Math.round(parseFloat(getComputedStyle(wm).fontSize));
      var over=de.scrollWidth>de.clientWidth?' OVERFLOW':'';
      var gv=d.querySelector('.gauge__value:last-child');
      out.push(w+'px: display '+fs+'px/'+lines+'L wordmark '+wmfs+'px h2='+Math.round(disp.getBoundingClientRect().width)+over);
      f.remove();
      if(out.length===widths.length){
        var pre=document.createElement('pre'); pre.id='results'; pre.textContent=out.join('\\n'); document.body.appendChild(pre);
      }
    });
  });
});
</script>
"""
